.usage-trend-card { padding-bottom: var(--space-4); }.daily-chart-wrap { position: relative; padding-left: 42px; }.daily-axis { position: absolute; top: 0; bottom: 27px; left: 0; display: flex; flex-direction: column; justify-content: space-between; color: var(--color-text-muted); font-family: var(--font-mono); font-size: 10px; }.daily-chart { display: block; width: 100%; height: 230px; overflow: visible; }.chart-grid-line { stroke: var(--color-border-soft); stroke-dasharray: 4 5; }.daily-bar { fill: var(--color-accent-brand); opacity: .82; transition: opacity .2s, fill .2s; }.daily-bar:hover { fill: var(--color-accent-brand-hover); opacity: 1; }.daily-labels { display: grid; grid-template-columns: repeat(auto-fit, minmax(36px, 1fr)); gap: 2px; color: var(--color-text-muted); font-family: var(--font-mono); font-size: 10px; text-align: center; }.daily-labels span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.empty-chart { min-height: 180px; display: grid; place-items: center; color: var(--color-text-muted); }.usage-hint { margin: 0; color: var(--color-text-muted); font-size: var(--text-caption-size); }.usage-records-card { padding-bottom: var(--space-3); }.usage-records-card .card-heading { margin-bottom: var(--space-3); }.usage-records-card :deep(.n-data-table .n-data-table-td) { cursor: pointer; }.usage-detail-panel { display: grid; grid-template-columns: repeat(2, minmax(220px, 1fr)); gap: 28px; padding: 4px 24px 8px; }.usage-detail-group-title { margin-bottom: 8px; color: var(--color-text-secondary); font-size: 13px; font-weight: 600; }.usage-detail-row { display: flex; justify-content: space-between; gap: 24px; padding: 6px 0; border-bottom: 1px solid var(--color-border-soft); }.usage-detail-row span { color: var(--color-text-muted); }
